# Confirmation (not used in the proof): the classes of the equivalence generated by the relations
# R_l of the step of Theorem (F^93_k), for each exterior cell (u0,v0), computed by closure on {0,1}^6.
# The step proves them by hand: one class if (u0,v0) != (0,0); classes u1v1=0 (48) and u1v1=1 (16) otherwise.
import itertools
def f(a,b,c,rule=93): return (rule>>(4*a+2*b+c))&1
B=(0,1)
def rels(p,q,which=(0,1,-1)):
    S=list(itertools.product(B,repeat=6))
    E=set()
    for s in S:
        u,v,w,x,y,z=s
        if 0 in which:
            for (w2,x2,y2,z2) in itertools.product(B,repeat=4):
                if (u,v)==(0,0) and (w2&x2)!=(w&x): continue
                E.add((s,(u,v,w2,x2,y2,z2)))
        if 1 in which:
            al=u^f(q,v,x); be=w^f(v,x,z)
            for (x2,z2,be2,y2) in itertools.product(B,repeat=4):
                if (v,al)==(0,0) and (x2&be2)!=(x&be): continue
                u2=al^f(q,v,x2); w2=be2^f(v,x2,z2)
                E.add((s,(u2,v,w2,x2,y2,z2)))
        if -1 in which:
            ga=v^f(p,u,w); de=x^f(u,w,y)
            for (w2,y2,de2,z2) in itertools.product(B,repeat=4):
                if (ga,u)==(0,0) and (de2&w2)!=(de&w): continue
                v2=ga^f(p,u,w2); x2=de2^f(u,w2,y2)
                E.add((s,(u,v2,w2,x2,y2,z2)))
    return S,E
def classes(S,E):
    par={s:s for s in S}
    def fd(a):
        while par[a]!=a: par[a]=par[par[a]]; a=par[a]
        return a
    for a,b in E: par[fd(a)]=fd(b)
    cl={}
    for s in S: cl.setdefault(fd(s),[]).append(s)
    return list(cl.values())
if __name__=='__main__':
    for p,q in itertools.product(B,repeat=2):
        S,E=rels(p,q)
        sym=all((b,a) in E for a,b in E)
        cl=classes(S,E)
        desc=[(len(c), sorted(set(s[0]&s[1] for s in c))) for c in cl]
        print((p,q),'symmetric',sym,'classes',desc)
        assert sym
        assert sorted(desc)==([(16,[1]),(48,[0])] if (p,q)==(0,0) else [(64,[0,1])])
